def main(args):
    """固定等待（秒）。用于等页面把表格渲染出来。"""
    import time
    try:
        sec = float(args.get('seconds') or 0)
    except Exception:
        sec = 0.0
    sec = max(0.0, min(sec, 600.0))
    time.sleep(sec)
    return {"slept": sec}

